def native_media(code):
 config_path=root/'reel-media.json'
 media=json.loads(config_path.read_text()) if config_path.exists() else {}
 source=media.get(code)
 if not source:return None
 if not isinstance(source,str):raise ValueError('Reel media must be a path or HTTPS video URL')
 parsed=urlparse(source)
 if parsed.scheme:
  if parsed.scheme!='https' or not parsed.netloc or parsed.username or parsed.password:raise ValueError('Use a public HTTPS video URL without credentials')
 else:
  resolved=(out/source).resolve()
  if not resolved.is_relative_to(out.resolve()) or not resolved.is_file():raise ValueError('Missing local Reel media: '+source)
 if Path(parsed.path).suffix.lower() not in ['.mp4','.webm']:raise ValueError('Use an MP4 or WebM source file')
 return source

